void *LANGameInfo::getLANSlot(Int slotNum)
{
	if (slotNum < 0 || slotNum >= MAX_SLOTS)
		return 0;
	return &m_LANSlot[slotNum];
}

Int LANGameInfo::getLocalSlotNum() const
{
	Int localSlot = -1;
	if (m_inGame)
	{
		for (Int i = 0; i < MAX_SLOTS; ++i)
		{
			const LANGameSlot *slot = (const LANGameSlot *)((LANGameInfo *)this)->getLANSlot(i);
			if (slot->isLocalPlayer())
			{
				localSlot = i;
				break;
			}
		}
	}
	return localSlot;
}

